


--Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) AS revenue
FROM customer
GROUP BY gender

--Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes' AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer)


-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased,
	COUNT(review_rating) AS "total_review",
	ROUND(AVG(review_rating::numeric),2) AS "Average Product Rating"
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC, total_review DESC
LIMIT 5;

--Q4. How does average purchase amount compare across ALL shipping types?
SELECT 
	shipping_type,
	COUNT(customer_id) AS total_orders,
	ROUND(AVG(purchase_amount),2) AS "Average purchase amount"
FROM customer
GROUP BY shipping_type
ORDER BY AVG(purchase_amount) DESC


--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
SELECT 
	subscription_status, 
	COUNT(customer_id) total_customers,
	ROUND(AVG(purchase_amount),2) AS Avg_spend,
	SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue, Avg_spend

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT 
	item_purchased,
	ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;


-- Q7. Segment customers into loyalty tiers by previous purchases and count each tier.
--     New 1-5 | Returning 6-20 | Loyal 21-40 | VIP 41-50.
WITH customer_type AS (
    SELECT customer_id,
           previous_purchases,
           CASE
               WHEN previous_purchases <= 5  THEN 'New'
               WHEN previous_purchases <= 20 THEN 'Returning'
               WHEN previous_purchases <= 40 THEN 'Loyal'
               ELSE 'VIP'
           END AS customer_segment
    FROM customer
)
SELECT customer_segment,
	COUNT(*) AS number_of_customers,
    ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS pect_of_customers
FROM customer_type
GROUP BY customer_segment;


--Q8. What are the top 3 most purchased products within each category?
WITH item_count AS (
	SELECT category,
		item_purchased,
		COUNT(customer_id) AS total_orders,
		ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) as item_rank
	FROM customer
	GROUP BY category, item_purchased
) 

SELECT category, item_rank, item_purchased, total_orders
FROM item_count
WHERE item_rank <= 3
ORDER BY category, item_rank;
 
--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
	COUNT(customer_id) AS repeat_buyers,
	ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS pct_of_repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status
ORDER BY repeat_buyers DESC;


--Q10. What is the revenue contribution of each age group? 
SELECT 
	age_group,
    COUNT(*) AS total_orders,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_order,
    ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER (), 2) AS revenue_percentage
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;


-- Q11. Which product categories are most popular among male and female customers?
SELECT gender, category, COUNT(customer_id) AS customer_count
FROM customer
GROUP BY gender, category
ORDER BY customer_count DESC

-- Q.12 Which age group contributes the most purchases in each product category?
WITH age_category AS (
	SELECT
		category,
		age_group,
		COUNT(*) AS total_purchases,
		DENSE_RANK() OVER(PARTITION BY category ORDER BY COUNT(*) DESC) AS age_rank
	FROM customer
	GROUP BY category, age_group
)

SELECT category, age_group, total_purchases, age_rank
FROM age_category
WHERE age_rank = 1
ORDER BY total_purchases DESC;


-- Q13. What are the top 3 most popular products in each season?
WITH seasonal_products AS (
	SELECT 
		season,
		item_purchased,
		COUNT(*) AS total_purchases,
		DENSE_RANK() OVER(PARTITION BY season ORDER BY COUNT(*) DESC) AS product_rank
	FROM customer
	GROUP BY season, item_purchased
)

SELECT season,
	item_purchased,
	total_purchases,
	product_rank
FROM seasonal_products
WHERE product_rank <= 3
ORDER BY season, product_rank;

-- Q14. Which product categories contribute the highest percentage of total revenue?
SELECT 
	category,
	SUM(purchase_amount) AS total_revenue,
	ROUND(100.0 * SUM(purchase_amount) /   SUM(SUM(purchase_amount)) OVER ()  , 2) AS revenue_percentage
FROM customer
GROUP BY category
ORDER BY revenue_percentage DESC;

-- Q15. Which products have high purchase volumes but below-average ratings?
WITH product_performance AS (
	SELECT 
		item_purchased,
		COUNT(*) AS total_purchases,
		ROUND(AVG(review_rating::numeric),2) AS avg_rating
	FROM customer
	GROUP BY item_purchased
)

SELECT 
	item_purchased,
	total_purchases,
	avg_rating
FROM product_performance
WHERE total_purchases > (
		SELECT AVG(total_purchases)
		FROM product_performance
	) 
	AND
	avg_rating < (
		SELECT AVG(review_rating::numeric)
		FROM customer
	)
ORDER BY total_purchases DESC;


-- Q16. How does purchase frequency differ between subscribers and non-subscribers?
SELECT subscription_status,
	frequency_of_purchases,
	COUNT(*) AS total_customers,
	ROUND(
		100.0 * COUNT(*)/
		SUM(COUNT(*)) OVER(PARTITION BY subscription_status),
		2) AS frequency_percentage
FROM customer
GROUP BY subscription_status, frequency_of_purchases
ORDER  BY subscription_status, total_customers DESC


-- Q17. Do customers who use discounts have higher previous purchase counts?
SELECT
    discount_applied,
    COUNT(DISTINCT customer_id) AS total_customers,
    ROUND(AVG(previous_purchases::numeric), 2) AS avg_previous_purchases,
    SUM(previous_purchases) AS total_previous_purchases
FROM customer
GROUP BY discount_applied
ORDER BY avg_previous_purchases DESC;

-- Q18. Which product category is most popular in each season?
WITH seasonal_categories AS (
    SELECT
        season,
        category,
        COUNT(*) AS total_purchases,
        DENSE_RANK() OVER (
            PARTITION BY season
            ORDER BY COUNT(*) DESC
        ) AS category_rank
    FROM customer
    GROUP BY season, category
)
SELECT
    season,
    category,
    total_purchases,
    category_rank
FROM seasonal_categories
WHERE category_rank = 1
ORDER BY season;
